snippets.nodeEsm:
import { readFileSync } from "node:fs";
import { Renderer } from "bm-render"; // full profile, ready on import

const renderer = new Renderer();
renderer.registerFont({ name: "Inter", data: readFileSync("Inter-Regular.ttf") });
const png = renderer.renderSync(
  { type: "container", style: { display: "flex", width: "100%", height: "100%", alignItems: "center", justifyContent: "center", backgroundColor: "#7c3aed" },
    children: [{ type: "text", text: "Hello", style: { fontFamily: "Inter", fontSize: 64, color: "white" } }] },
  { width: 1200, height: 630 }, // format: "png" (default) | "jpeg" | "webp" | "raw" (+ "ico" on full)
);

