snippets.bundler:
import { init, Renderer } from "bm-render/core"; // or /standard, /full

await init(); // the bundler emits bm_render.core.wasm (new URL(..., import.meta.url))
const renderer = new Renderer();
renderer.registerFont(new Uint8Array(await (await fetch("/Inter-Regular.ttf")).arrayBuffer()));
const png = await renderer.render(node, { width: 1200, height: 630 });

